mapper.select:
SELECT eis.id, eis.system_id AS systemId, eis.name, eis.code, eis.version, eis.desc AS description, eis.category_count AS categoryCount, eis.item_count AS itemCount, eis.object_type_id AS objectTypeId, eis.status_id AS statusId, eis.create_by AS createBy, eis.biz_create_time AS bizCreateTime, eis.biz_update_time AS bizUpdateTime,
sot.name AS objectTypeName, ss.name AS statusName, creator.user_name AS createByName
FROM eval_index_system eis
LEFT JOIN sys_object_type sot ON eis.object_type_id = sot.type_id
LEFT JOIN sys_status ss ON eis.status_id = ss.status_id LEFT JOIN sys_user creator ON eis.create_by = creator.user_id
WHERE eis.deleted = 0 AND eis.tenant_id = #{reqVO.tenantId}
AND eis.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND eis.code = #{reqVO.code}
AND eis.system_id = #{reqVO.systemId}
AND eis.object_type_id = #{reqVO.objectTypeId}
AND eis.status_id = #{reqVO.statusId}
AND eis.version = #{reqVO.version}
ORDER BY eis.biz_create_time DESC
